package com.fintaxpro;
import java.io.IOException;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
/** Cookie mutations must originate from the configured same-origin frontend. */
@Component public class OriginFilter extends OncePerRequestFilter{final String origin;OriginFilter(@Value("${fintax.frontend-origin}")String o){origin=o;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain chain)throws ServletException,IOException{String o=r.getHeader("Origin");if(!ListHolder.SAFE.contains(r.getMethod())&&o!=null&&!o.equals(origin)){s.setStatus(403);s.setContentType("application/json");s.getWriter().write("{\"error\":\"Invalid request origin.\"}");return;}chain.doFilter(r,s);}static class ListHolder{static final java.util.Set<String> SAFE=java.util.Set.of("GET","HEAD","OPTIONS");}}
